    questions: [
      { q: "How long has B worked as a developer?", a: "Three years", wrong: ["One year", "Ten years", "Six months"] },
      { q: "Which languages does B use?", a: "JavaScript and Python", wrong: ["Only Java", "Only C", "French and Spanish"] }
    ]
